package com.distributedexam.server.monitoring; import com.distributedexam.common.*; import com.distributedexam.dao.*; import com.distributedexam.remote.MonitoringRemote; import java.rmi.*; import java.rmi.server.UnicastRemoteObject; import java.util.*;
public class MonitoringManager extends UnicastRemoteObject implements MonitoringRemote { private final EventManager events=new EventManager(new EventDAOImpl()); private final IncidentManager incidents=new IncidentManager(new IncidentDAOImpl(),events); public MonitoringManager()throws RemoteException{} public int reportIncident(Incident i)throws Exception{return incidents.report(i);} public boolean resolveIncident(int id)throws Exception{return incidents.resolve(id);} public List<Incident> getOpenIncidents()throws Exception{return incidents.open();} public List<Incident> getIncidentsByRoom(int id)throws Exception{return incidents.room(id);} public void logEvent(ExamEvent e)throws Exception{events.log(e);} public List<ExamEvent> getRecentEvents(int l)throws Exception{return events.recent(l);} }
